using System.Text.Json;
using Quill.Windows;
using Xunit;
namespace Quill.Windows.Tests;
public sealed class DomainTests {
 [Theory][InlineData(DictationState.Idle,false,false,false)][InlineData(DictationState.Idle,true,true,true)][InlineData(DictationState.Idle,true,false,false)][InlineData(DictationState.Recording,false,false,true)][InlineData(DictationState.Transcribing,false,false,true)][InlineData(DictationState.Paste,false,false,true)][InlineData(DictationState.Error,false,false,true)]
 public void ActiveDictationAlwaysHasAVisibleControlWithoutChangingIdlePreference(DictationState state,bool enabled,bool visible,bool expected) => Assert.Equal(expected,SessionPresentation.ShowFloatingControl(enabled,visible,state));
 [Fact] public void ProviderOverloadHasUsefulCopyAndDoesNotMasqueradeAsQuotaOrBadKey() { Assert.Equal("provider_busy",DictationController.Code(new ProviderException("provider_error",503))); Assert.Equal("quota",DictationController.Code(new ProviderException("quota",429))); Assert.Equal("bad_key",DictationController.Code(new ProviderException("bad_key",401))); }
 [Fact] public void ReaddingCustomWordReplacesExistingMappingIgnoringCase() { var words = new List<CustomWord> {new("quell","Old"),new("other","Other"),new("QUELL","Second")}; Words.Upsert(words,"  Quell "," Quill "); Assert.Equal(new[] {new CustomWord("other","Other"),new CustomWord("Quell","Quill")},words); Assert.Equal("Quill",Words.Apply("quell",words)); }
 [Fact] public void BlankCustomWordUpsertLeavesVocabularyUnchanged() { var words = new List<CustomWord> {new("word","Word")}; Words.Upsert(words," ","value"); Words.Upsert(words,"word"," "); Assert.Equal(new[] {new CustomWord("word","Word")},words); }
 [Fact] public void GlobalShortcutMatchesDocumentedControlWindowsSpace() { Assert.True((HotkeyService.Modifiers & 0x0008) != 0); Assert.True((HotkeyService.Modifiers & 0x0002) != 0); Assert.Equal(0u,HotkeyService.Modifiers & 0x0004); }
 public static IEnumerable<object[]> AndroidCleanupCases() { using var json = JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"parity","cleanup.json"))); return json.RootElement.GetProperty("cases").EnumerateArray().Select(item => new object[] { item.GetProperty("raw").GetString()!,item.GetProperty("cleaned").GetString()!,item.GetProperty("accepted").GetBoolean() }).ToArray(); }
 [Theory][MemberData(nameof(AndroidCleanupCases))] public void CleanupMatchesAndroid(string raw,string clean,bool expected) => Assert.Equal(expected,CleanupGuard.PreservesMeaning(raw,clean));
 [Fact] public void ShippedDefaultsMatchCurrentAndroid() { var s = new QuillSettings(); Assert.Equal(Provider.Groq,s.Provider); Assert.Equal("whisper-large-v3-turbo",s.SpeechModel); Assert.Equal("en",s.Language); Assert.True(s.UseCleanup); Assert.True(s.CleanupAutomatic); Assert.Equal(60,s.HistoryRetentionMinutes); Assert.Equal(300,s.SessionCapSeconds); Assert.False(s.PrivateMode); Assert.False(s.OnboardingComplete); Assert.False(s.CrashReportingEnabled); }
 [Theory][InlineData(Provider.Groq,true)][InlineData(Provider.Gemini,true)][InlineData(Provider.OpenRouter,true)][InlineData(Provider.OpenAI,false)][InlineData(Provider.Custom,false)] public void AutomaticCleanupUsesOnlyKnownFreeProviders(Provider provider,bool expected) { var s = new QuillSettings { Provider = provider }; Assert.Equal(expected,s.UseCleanup); Assert.Equal(provider,s.EffectiveCleanupProvider); }
 [Fact] public void ManualCleanupRemainsIndependent() { var s = new QuillSettings { Provider = Provider.Gemini,CleanupAutomatic = false,CleanupProvider = Provider.OpenAI,CleanupModel = "selected-model" }; Assert.True(s.UseCleanup); Assert.Equal(Provider.OpenAI,s.EffectiveCleanupProvider); Assert.Equal("selected-model",s.EffectiveCleanupModel); }
 [Theory][InlineData("https://example.test/v1/","https://example.test/v1")][InlineData(" https://example.test/proxy/v1 ","https://example.test/proxy/v1")] public void EndpointCanonicalization(string input,string expected) => Assert.Equal(expected,Providers.ValidateEndpoint(input));
 [Theory][InlineData("http://example.test")][InlineData("https://user:password@example.test")][InlineData("https://example.test?q=1")][InlineData("https://example.test/#secret")][InlineData("file:///example")][InlineData("junk")] public void EndpointRejectsCredentialLeakPaths(string url) => Assert.Throws<ArgumentException>(() => Providers.ValidateEndpoint(url));
 [Fact] public void SilenceHasStartupGraceAndConservativeWindow() { var d = new SilenceDetector(); Assert.False(d.Observe(0,0)); Assert.False(d.Observe(0,1999)); Assert.False(d.Observe(0,2000)); Assert.False(d.Observe(0,5499)); Assert.True(d.Observe(0,5500)); }
 [Fact] public void SpeechResetsQuietWindow() { var d = new SilenceDetector(); d.Observe(0,2000); Assert.False(d.Observe(600,5400)); Assert.False(d.Observe(0,5500)); Assert.False(d.Observe(0,8999)); Assert.True(d.Observe(0,9000)); }
 [Fact] public void WavHasBoundedDeterministicFormat() { var pcm = new byte[32000]; var wav = AudioRecorder.Wav(pcm); Assert.Equal(32044,wav.Length); Assert.Equal("RIFF",System.Text.Encoding.ASCII.GetString(wav,0,4)); Assert.Equal(32036,BitConverter.ToInt32(wav,4)); Assert.Equal(16000,BitConverter.ToInt32(wav,24)); Assert.Equal(1,BitConverter.ToInt16(wav,22)); Assert.Equal(16,BitConverter.ToInt16(wav,34)); Assert.Equal(32000,BitConverter.ToInt32(wav,40)); }
 [Theory][InlineData("hello world",5,5,"quill","helloquill world")][InlineData("hello",5,5,"Quill","hello Quill")][InlineData("hello!",6,6,"Quill","hello! Quill")][InlineData("before after",7,12,"there","before there")][InlineData("hello",-2,100,"bye","bye")][InlineData("hi,",2,2," friend","hi friend,")][InlineData("existing",0,0,"prefix ","prefix existing")] public void ComposerPreservesAdjacentText(string current,int start,int end,string insert,string expected) => Assert.Equal(expected,InsertionComposer.Insert(current,start,end,insert));
 [Fact] public void WholeWordsAndLiteralReplacement() { var words = new[] { new CustomWord("cat","$1 dog"),new CustomWord("quill app","Quill") }; Assert.Equal("$1 dog category, Quill!",Words.Apply("Cat category, QUILL APP!",words)); }
 [Theory][InlineData("outlook",WritingStyle.Formal)][InlineData("slack",WritingStyle.Formal)][InlineData("ms-teams",WritingStyle.Formal)][InlineData("discord",WritingStyle.Casual)][InlineData("whatsapp",WritingStyle.Neutral)][InlineData("telegram",WritingStyle.Neutral)][InlineData("signal",WritingStyle.Neutral)][InlineData("chrome",WritingStyle.Neutral)] public void NativeAppStylesMirrorAndroidNames(string app,WritingStyle expected) => Assert.Equal(expected,new QuillSettings { DefaultStyle = WritingStyle.Casual }.StyleFor(app));
 [Fact] public void StyleOverridePrecedesCuratedWhichPrecedesGlobal() { var s = new QuillSettings { DefaultStyle = WritingStyle.Casual }; Assert.Equal(WritingStyle.Casual,s.StyleFor("unknown")); Assert.Equal(WritingStyle.Formal,s.StyleFor("slack")); s.AppStyles["slack"] = WritingStyle.Neutral; Assert.Equal(WritingStyle.Neutral,s.StyleFor("slack")); }
 [Fact] public void ContactImportReadsNamesOnly() { var names = VCardNames.Parse("BEGIN:VCARD\r\nFN:Anne-Marie O'Brien\r\nEMAIL:secret@example.com\r\nTEL:555-0100\r\nFN:Alice\r\n Bob\r\nEND:VCARD"); Assert.Equal(new[] {"AliceBob","Anne-Marie O'Brien"},names); Assert.DoesNotContain(names,n => n.Contains("555") || n.Contains('@')); }
 [Fact] public void ContactVocabularyMatchesAndroidRules() { var names = ContactVocabulary.Extract([" Dr. A Smith ","dr. a smith","Anne-Marie O'Brien","person123","person@example.com","A","one two three four five","😀 Bob"]); Assert.Equal(new[] {"Dr. A Smith","Dr.","Smith","Anne-Marie O'Brien","Anne-Marie","O'Brien"},names); }
 [Fact] public void CopyManifestVectorsMatchRuntimeExtractor() { using var json = JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"copy-manifest.json"))); foreach (var vector in json.RootElement.GetProperty("placeholderTestVectors").EnumerateArray()) Assert.Equal(vector.GetProperty("tokens").EnumerateArray().Select(t => t.GetString()),CopyFormatter.Signature(vector.GetProperty("input").GetString()!)); }
 [Fact] public void CopyFormatterSupportsReorderRepeatImplicitAndEscapes() { Assert.Equal("B A A",CopyFormatter.Format("%2$s %1$s %1$s","A","B")); Assert.Equal("three = 3",CopyFormatter.Format("%s = %d","three",3)); Assert.Equal("03.14",CopyFormatter.Format("%05.2f",3.14159)); Assert.Equal("100%" + Environment.NewLine + "50% off",CopyFormatter.Format("100%%%n50% off")); Assert.Equal("   abc",CopyFormatter.Format("%6.3s","abcdef")); }
 [Fact] public void EveryCatalogManifestDefaultMatchesAndPlaceholdersAreComplete() { var copy = new CopyCatalog(); using var json = JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"copy-manifest.json"))); var keys = json.RootElement.GetProperty("keys"); foreach (var (key,value) in copy.All) { Assert.Equal(value,keys.GetProperty(key).GetProperty("default").GetString()); Assert.Equal(CopyFormatter.Signature(value),keys.GetProperty(key).GetProperty("placeholders").EnumerateArray().Select(v => v.GetString())); } }
}
